create role anon nologin;
create role authenticated nologin;
create role service_role nologin;
create schema auth;
create function auth.role() returns text language sql stable as $$ select nullif(current_setting('request.jwt.claim.role',true),'') $$;
create function public.normalize_part_code(x text) returns text language sql immutable as $$ select upper(regexp_replace(coalesce(x,''),'[^a-zA-Z0-9]','','g')) $$;
create table public.organizations(id uuid primary key);
create table public.brands(id uuid primary key,organization_id uuid not null references public.organizations(id),name text not null);
create table public.catalog_external_sources(id uuid primary key default gen_random_uuid(), organization_id uuid not null, source_key text not null, display_name text, source_owner text, source_type text not null default 'open_web', is_active boolean not null,license_posture text not null,base_url text,robots_posture text,rate_limit_posture text,metadata jsonb not null, unique(organization_id,source_key));
create table public.catalog_products(id uuid primary key,organization_id uuid not null references public.organizations(id),brand_id uuid not null references public.brands(id),product_code text not null,normalized_code text generated always as (public.normalize_part_code(product_code)) stored,oem_no text,normalized_oem text generated always as (public.normalize_part_code(oem_no)) stored,vehicle text,updated_at timestamptz, unique(organization_id,brand_id,normalized_code), unique(id,organization_id));
create table public.catalog_product_source_records(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),catalog_product_id uuid not null,source_key text not null,source_url text not null,source_product_id text,retrieved_at timestamptz not null,payload_fingerprint text not null,unique(id,organization_id),unique(organization_id,catalog_product_id,source_key,payload_fingerprint),foreign key(catalog_product_id,organization_id) references public.catalog_products(id,organization_id));
create table public.catalog_product_identifiers(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),catalog_product_id uuid not null,identifier_type text not null,authority text,value text not null,normalized_value text generated always as(public.normalize_part_code(value)) stored,source_record_id uuid,foreign key(catalog_product_id,organization_id) references public.catalog_products(id,organization_id),foreign key(source_record_id,organization_id) references public.catalog_product_source_records(id,organization_id));
create unique index identifiers_uniq on public.catalog_product_identifiers(organization_id,catalog_product_id,identifier_type,coalesce(authority,''),normalized_value);
create table public.supplier_prices(id uuid primary key,product_code text,buy_price numeric);
